import { test, expect, BASE_URL } from '../../utils/setup';
import { selectQOStatus } from '../../utils/OrderHelper';

test.use({ user: 'DemoProdDirector' });

test("VC2-9267: Investigate missing script polish option in QO", async ({ page }) => {
  await test.step('Navigate to production orders', async () => {
    await page.goto(`${BASE_URL}/#/vpro/production-orders/folder/all`);
    await page.getByRole('link', { name: 'New Request' }).click();
  });

  await test.step('Select adtype and set status to Needs Producing', async () => {
    // Adtype list contains disabled section headers (TERRESTRIAL, DIGITAL, …).
    // Pick "Radio Commercial" explicitly so we always land on a producible
    // adtype whose form exposes the polish button.
    await page.getByRole('combobox', { name: 'Select an Adtype' }).click();
    const radioCommercial = page.locator('.p-select-overlay [role="option"], [role="listbox"] [role="option"]')
      .filter({ hasText: /^Radio Commercial$/i })
      .first();
    await radioCommercial.waitFor({ state: 'visible', timeout: 10000 });
    await radioCommercial.click({ force: true });

    // Select Status is disabled until adtype resolves; the helper waits internally.
    await selectQOStatus(page, 'Needs Producing');
  });

  await test.step('Verify script polish button is visible', async () => {
    // #vfields-polish-btn-52552 contains a database field ID that changes across deploys.
    // Match by ID prefix so it works regardless of the field ID in the current environment.
    await expect(page.locator('[id^="vfields-polish-btn"]').first()).toBeVisible({ timeout: 20000 });
  });

  await test.step('Fill script and trigger polish', async () => {
    await page.locator('.ql-editor').first().click();
    await page.locator('.ql-editor').first().fill('super awesome script');
    // The polish button is enabled once script text exists — allow the editor
    // blur/model-sync (~500ms) to arm the button before clicking, and use
    // scrollIntoView + force to bypass PrimeNG overlay hit-testing races.
    const polishBtn = page.locator('[id^="vfields-polish-btn"]').first();
    await polishBtn.scrollIntoViewIfNeeded().catch(() => {});
    await polishBtn.waitFor({ state: 'visible', timeout: 10000 });
    await page.waitForTimeout(500);
    await polishBtn.click({ force: true, timeout: 15000 });
  });

  await test.step('Confirm polish and verify success', async () => {
    // Polish is an AI-driven pipeline — the confirmation dialog wording can
    // shift ("Replace the current script with:", etc.) and the polish API can
    // take 15-30s. Wait for the confirm button by shape, not exact prose.
    const yesBtn = page.getByRole('button', { name: /^(Yes|Confirm|Replace|OK)$/i }).first();
    await expect(yesBtn).toBeVisible({ timeout: 45000 });
    await yesBtn.click();
    // "Script polished" toast is app-owned copy; keep the exact match but
    // extend the window in case the polish API is slow.
    await expect(page.getByText(/Script polished/i).first()).toBeVisible({ timeout: 30000 });
  });
});